expected.fmt:
from "@std/test.ms" import expect_equal

def map_total(values: Map[String, Int]) -> Int:
    var total = 0

    for entry in values:
        let {value} = entry
        total += value

    return total

def set_total(values: Set[Int]) -> Int:
    var total = 0
    for value in values:
        total += value
    return total

test "map entry type":
    let entry = MapEntry[String, Int]("a", 3)
    try expect_equal(entry.key, "a")
    try expect_equal(entry.value, 3)
